        redirect: "manual",
        // @ts-expect-error undici/node specific
        duplex: "half",
        ...init,
        headers,
      });
    };
  });

  afterAll(async () => {
    server.closeAllConnections();
    await new Promise<void>((resolve, reject) =>
      server.close((err) => (err ? reject(err) : resolve())),
    );
    server = undefined!;
  });

  beforeEach(async () => {
    handler = toNodeHandler(ctx.app);
  });

  afterEach(() => {
    handler = undefined!;
  });

